body {
    margin: 0;
    font-family: Arial, sans-serif;
    color: #18332b;
    background-color: #f4f7f5;
}

img {
    display: block;
}

main {
    width: min(92%, 1100px);
    margin-inline: auto;
}

main {
    width: 92%;
    max-width: 1100px;
    margin-left: auto;
    margin-right: auto;
}

.encabezado,
.navegacion,
.portada,
.rutas {
    padding: 1rem;
}

.rutas {
    display: grid;
    gap: 1rem;
}

img {
    display: block;
    max-width: 100%;
    height: auto;
}

.tarjeta img {
    width: 100%;
    height: 220px;
    object-fit: cover;
}

@media (min-width: 700px) {
    .rutas {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 699px) {
    .navegacion {
        flex-direction: column;
    }
}

@media (min-width: 700px) and (max-width: 999px) {
    .portada {
        grid-template-columns: 1fr 1fr;
    }
}

@media (orientation: landscape) {
    /* Reglas para una vista más ancha que alta */
}

.navegacion {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 1rem;
    background-color: #dcebe3;
}

.navegacion a {
    padding: 0.75rem;
    color: #18332b;
    text-decoration: none;
}

@media (min-width: 700px) {
    .navegacion {
        flex-direction: row;
        justify-content: center;
    }
}

.portada {
    display: grid;
    gap: 1rem;
    margin-block: 1rem;
    background-color: white;
}

.portada > div {
    padding: 1rem;
}

@media (min-width: 700px) {
    .portada {
        grid-template-columns: 1.2fr 1fr;
        align-items: center;
    }
}

.rutas {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1rem;
}

@media (min-width: 700px) {
    .rutas {
        grid-template-columns: repeat(2, 1fr);
    }
}

.rutas {
    display: grid;
    grid-template-columns:
    repeat(auto-fit, minmax(min(100%, 260px), 1fr));
    gap: 1rem;
}

.lista-datos {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
}

.dato {
    flex: 1 1 220px;
}

.tarjeta,
.contenido {
    min-width: 0;
}

.contenido p,
.contenido a {
    overflow-wrap: anywhere;
}

h1 {
    font-size: clamp(2rem, 5vw, 4rem);
}

.accion {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 0.75rem 1rem;
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        scroll-behavior: auto;
        animation-duration: 0.01ms;
        animation-iteration-count: 1;
        transition-duration: 0.01ms;
    }
}

@media (prefers-color-scheme: dark) {
    body {
        color: #eef7f2;
        background-color: #10221c;
    }

    .tarjeta {
        background-color: #19372d;
    }
}

* {
    outline: 1px solid red;
}

* { box-sizing: border-box; }
body { margin: 0; font-family: Arial, sans-serif; }
img { display: block; max-width: 100%; height: auto; }

.contenido {
    width: min(92%, 1100px);
    margin-inline: auto;
}

.menu {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 1rem;
}

.presentacion,
.paradas {
    display: grid;
    gap: 1rem;
}

.parada {
    overflow: hidden;
    border: 1px solid #b8c7bf;
    border-radius: 0.75rem;
    background-color: white;
}

.parada h3,
.parada p {
    margin-inline: 1rem;
}

.parada img {
    width: 100%;
    height: 220px;
    object-fit: cover;
}

@media (min-width: 700px) {
    .menu {
        flex-direction: row;
        justify-content: center;
    }

    .presentacion {
        grid-template-columns: 1.2fr 1fr;
        align-items: center;
    }

    .paradas {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (min-width: 1000px) {
    .paradas {
        grid-template-columns: repeat(3, 1fr);
    }
}

.paradas {
    grid-template-columns:
    repeat(auto-fit, minmax(min(100%, 250px), 1fr));
}
